function e6d1bReadRequest(callerUserId: string | null): CompetitionRoomTournamentReadRequest {
  return { competitionId: 'competition-1', callerUserId }
}

async function e6d1bReadCurrentTournament(
  setup: Awaited<ReturnType<typeof e6c2aLockedMatch>>,
  callerUserId: string,
): Promise<JsonObject> {
  const before = e6c2aSnapshot(setup)
  const callStart = setup.calls.length
  const result = await setup.room.readTournament(e6d1bReadRequest(callerUserId))
  expect(result).toMatchObject({ ok: true, value: {
    competitionId: 'competition-1',
    projection: { ok: true, operation: 'tournamentView' },
  } })
  if (!result.ok) throw new Error(`formal tournament query failed: ${result.error.code}`)

  const meta = setup.sql.database.query(
    'SELECT revision, server_state_json FROM competition_meta WHERE singleton = 1',
  ).get() as { revision: number; server_state_json: string }
  const authoritativeState = JSON.parse(meta.server_state_json) as JsonObject
  expect(result.value.revision).toBe(meta.revision)
  expect(Object.keys(result.value).sort()).toEqual(result.value.publication
    ? ['competitionId', 'projection', 'publication', 'revision']
    : ['competitionId', 'projection', 'revision'])
  expect(Object.keys(result.value.projection).sort()).toEqual(['ok', 'operation', 'public'])
  expect(result.value.projection.public).toStrictEqual(authoritativeState.tournament)
  expect(setup.calls.slice(callStart).map(call => call.operation.type)).toEqual(['tournamentView'])
  const privateProjectionCheck = structuredClone(result)
  if (privateProjectionCheck.ok) delete privateProjectionCheck.value.publication
  expect(JSON.stringify(privateProjectionCheck)).not.toMatch(
    /"(?:serverState|private|announcement|captain|members|decks|rosterVersion|lockedRoster|binding|history|commandId|callerUserId)"\s*:/,
  )
  if (result.value.publication) {
    expect(Object.keys(result.value.publication).sort()).toEqual([
      'completedAtTrustedTimeMs', 'lockedDecks', 'replays',
    ])
  }
  expect(e6c2aSnapshot(setup)).toEqual(before)
  return result.value.projection.public as JsonObject
}

async function e6d1bSubmitWinner(
  setup: Awaited<ReturnType<typeof e6c2aLockedMatch>>,
  commandId: string,
) {
  return e6d1bSubmitScheduledWinner(setup, setup.matchId, commandId)
}

async function e6d1bSubmitScheduledWinner(
  setup: Awaited<ReturnType<typeof e6c2aLockedMatch>>,
  matchId: string,
  commandId: string,
  selectedWinner?: string,
  publishedBinding?: CompetitionGameBinding,
) {
  const row = setup.sql.database.query(
    'SELECT revision, last_trusted_time_ms, match_projection_json FROM competition_matches WHERE match_id = ?',
  ).get(matchId) as { revision: number; last_trusted_time_ms: number; match_projection_json: string }
  const match = ((JSON.parse(row.match_projection_json) as JsonObject).public as JsonObject).match as JsonObject
  const teams = (match.config as JsonObject).teams as string[]
  const nextGame = match.nextGame as JsonObject
  const provision = publishedBinding ? undefined : setup.sql.database.query(
    'SELECT binding_json FROM competition_game_provision WHERE match_id = ? AND game_number = ?',
  ).get(matchId, nextGame.gameNumber) as { binding_json: string } | undefined
  if (!publishedBinding && !provision) throw new Error('formal scheduled match has no persisted game binding')
  const binding = publishedBinding ?? JSON.parse(provision!.binding_json) as CompetitionGameBinding
  const winner = selectedWinner ?? teams[0]!
  if (!teams.includes(winner)) throw new Error('selected tournament winner is not a Match participant')
  const request: CompetitionRoomTerminalIngestRequest = {
    competitionId: 'competition-1',
    matchId,
    callerUserId: 'organizer-1',
    commandId,
    expectedMatchRevision: row.revision,
    trustedTimeMs: Math.max(row.last_trusted_time_ms, setup.meta().updated_trusted_time_ms) + 1,
    submissionId: `${commandId}-submission`,
    gameRecordId: `${commandId}-game-record`,
    rulingRecordId: `${commandId}-ruling`,
    startKind: binding.startKind,
    firstPlayer: match.nextFirstPlayer as string,
    terminalEvidence: {
      type: 'canonicalGameEnded',
      conclusion: {
        outcome: { type: 'winner', team: winner },
        causes: [{ type: 'directVictory', rule: 'e6d1b-current-query', team: winner }],
      },
    },
  }
  const result = await setup.room.ingestGameTerminal(request)
  return { ...result, submittedRequest: request }
}

async function e6d1bFinishScheduledTournament(
  setup: Awaited<ReturnType<typeof e6c2aLockedMatch>>,
  commandPrefix: string,
  selectWinner?: (roundKind: string, participants: string[]) => string,
  observeTerminal?: (
    roundKind: string,
    terminal: Awaited<ReturnType<typeof e6d1bSubmitScheduledWinner>>,
  ) => void,
): Promise<JsonObject> {
  for (let index = 0; index < 40; index += 1) {
    const tournament = await e6d1bReadCurrentTournament(setup, 'organizer-1')
    const stage = (tournament.stages as JsonObject[])[0]
    if (!stage) throw new Error('formal tournament query omitted its configured stage')
    if (stage.status === 'finished') return tournament

    const matches = (stage.rounds as JsonObject[])
      .flatMap(round => round.matches as JsonObject[])
    const scheduled = matches.find(match => match.status === 'pending' && match.started === false
      && Array.isArray(match.participants) && match.participants.length === 2)
    if (!scheduled || typeof scheduled.matchId !== 'string') {
      throw new Error(`formal ${setup.stage.format} schedule is not finished and has no legal pending match`)
    }

    const matchId = scheduled.matchId
    const scheduledRound = (stage.rounds as JsonObject[]).find(round => Array.isArray(round.matches)
      && (round.matches as JsonObject[]).some(match => match.matchId === matchId))
    if (!scheduledRound) throw new Error(`formal ${setup.stage.format} match has no containing round`)
    const participants = scheduled.participants as string[]
    const winner = selectWinner?.(String(scheduledRound.kind), participants) ?? participants[0]!
    if (!participants.includes(winner)) throw new Error('tournament winner selector returned a nonparticipant')
    persistTestPublishedRound(setup.sql, setup.stage.stageId, scheduledRound)
    const matchAlreadyMaterialized = setup.sql.database.query(
      'SELECT 1 FROM competition_matches WHERE match_id = ?',
    ).get(matchId)
    if (matchId !== setup.matchId && !matchAlreadyMaterialized) {
      const current = setup.meta()
      const started = await setup.room.startScheduledMatch({
        competitionId: 'competition-1',
        stageId: setup.stage.stageId,
        matchId,
        callerUserId: 'organizer-1',
        commandId: `${commandPrefix}-start-${index}`,
        expectedRevision: current.revision,
        trustedTimeMs: current.updated_trusted_time_ms + 1,
        referees: [],
      })
      if (!started.ok) throw new Error(`formal ${setup.stage.format} match start failed: ${started.error.code}`)

      const provisioned = await setup.room.provisionInitialScheduledGame({
        competitionId: 'competition-1',
        matchId,
        callerUserId: 'organizer-1',
        commandId: `${commandPrefix}-game-${index}`,
        expectedMatchRevision: 1,
        trustedTimeMs: setup.meta().updated_trusted_time_ms + 1,
      })
      if (!provisioned.ok) {
        throw new Error(`formal ${setup.stage.format} game provision failed: ${provisioned.error.code}`)
      }
    }

    const terminal = await e6d1bSubmitScheduledWinner(
      setup, matchId, `${commandPrefix}-terminal-${index}`, winner,
    )
    if (!terminal.ok) throw new Error(`formal ${setup.stage.format} result failed: ${terminal.error.code}`)
    observeTerminal?.(String(scheduledRound.kind), terminal)
  }
  throw new Error(`formal ${setup.stage.format} tournament did not finish within 40 scheduled matches`)
}

test.serial('ticket 16 completes a uniquely ranked single-stage tournament and publishes immutable data on retry', async () => {
  const setup = await e6c2aLockedMatch({
    format: 'roundRobin',
    matchFormat: { type: 'fixedGames', value: 1 },
    personalDeck: true,
    automaticRoundProgression: true,
  })
  const beforeFinish = e6c2aSnapshot(setup)
  expect(await setup.room.readTournament(e6d1bReadRequest(null)))
    .toMatchObject({ ok: false, error: { code: 'notParticipant' } })
  expect(e6c2aSnapshot(setup)).toEqual(beforeFinish)

  const terminal = await e6d1bSubmitWinner(setup, 'ticket16-final-result')
  expect(terminal).toMatchObject({ ok: true })
  expect((await e6d1bReadCurrentTournament(setup, 'organizer-1')).stages).toHaveLength(1)
  const completion = setup.sql.database.query(
    `SELECT competition_id, completed_at_trusted_time_ms, locked_decks_json, replay_refs_json
     FROM competition_completion WHERE competition_id = ?`,
  ).get('competition-1') as {
    competition_id: string
    completed_at_trusted_time_ms: number
    locked_decks_json: string
    replay_refs_json: string
  } | undefined
  expect(completion).toBeDefined()
  expect(Number(completion?.completed_at_trusted_time_ms)).toBeGreaterThanOrEqual(
    Number(setup.meta().updated_trusted_time_ms),
  )
  const decks = JSON.parse(completion!.locked_decks_json) as JsonObject[]
  expect(decks).toHaveLength(2)
  expect(decks.map(team => team.teamId).sort()).toEqual(['team-a', 'team-b'])
  expect(JSON.stringify(decks)).toContain('a-1-private-deck')

  const firstPublicRead = await setup.room.readTournament(e6d1bReadRequest(null))
  expect(firstPublicRead).toMatchObject({ ok: true, value: {
    publication: {
      completedAtTrustedTimeMs: completion?.completed_at_trusted_time_ms,
      lockedDecks: decks,
      replays: [{ matchId: setup.matchId, gameNumber: 1 }],
    },
  } })
  if (!firstPublicRead.ok) throw new Error('completed tournament was not public')
  const publishedReplays = JSON.parse(completion!.replay_refs_json) as JsonObject[]
  expect(firstPublicRead.value.publication?.replays).toEqual(publishedReplays)
  expect(firstPublicRead.value.publication?.replays[0]?.replayId).toBe(
    `competition:competition-1:${setup.provisioned?.ok ? setup.provisioned.value.gameId : ''}`,
  )

  const beforeRetry = e6c2aSnapshot(setup)
  await (setup.room as unknown as { completeCompetitionIfReady: () => Promise<void> })
    .completeCompetitionIfReady()
  expect(e6c2aSnapshot(setup)).toEqual(beforeRetry)
  expect(await setup.room.readTournament(e6d1bReadRequest(null))).toEqual(firstPublicRead)

  const restarted = new CompetitionRoomClass(stateFor(setup.sql, setup.alarm), setup.env, setup.adapter)
  const beforeRestartRead = e6c2aSnapshot(setup)
  expect(await restarted.readTournament(e6d1bReadRequest(null))).toEqual(firstPublicRead)
  expect(e6c2aSnapshot(setup)).toEqual(beforeRestartRead)
})

